const name = ($json.query?.name || 'report').toString().trim();
const theme = ($json.query?.theme || 'light').toLowerCase()==='dark' ? 'dark' : 'light';
const file = `/data/reports/${name}_${theme}.html`;
return [{ json: { name, theme, file } }];

// Inietta CSS di stampa "bello" + rinomina il binario in index.html per Gotenberg
const PRINT_CSS = `
<style id="pdf-print-style">
  :root{
    --bg:#ffffff; --paper:#ffffff; --text:#0f172a; --muted:#64748b; --subtle:#8a94a6;
    --border:#e6ebf2; --border-strong:#d9e0ea; --accent:#0ea5e9; --zebra:#f9fbff;
    --shadow:0 4px 16px rgba(2,6,23,.08);
  }
  @page { size: A4; margin: 12mm 12mm 14mm 12mm; }
  html,body{height:auto!important}
  body{
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", "Liberation Sans", sans-serif;
    font-size: 12pt; line-height: 1.5; color: var(--text); background: var(--bg);
    -webkit-print-color-adjust: exact; print-color-adjust: exact;
  }

  /* layout */
  .wrap{max-width: 920px; margin: 0 auto;}
  .no-print, .btns, .btn { display: none !important; }
  .section{margin: 18pt 0; break-inside: avoid; page-break-inside: avoid;}

  /* title / meta */
  .title-card{
    background: var(--paper); border:1px solid var(--border); border-radius: 18px;
    padding: 18pt; box-shadow: var(--shadow); margin: 8pt 0 18pt;
  }
  h1{font-size: 28pt; margin: 0 0 6pt; letter-spacing:.2px}
  .subtitle,.meta{color:var(--muted); font-size:10.5pt}

  /* generic cards */
  .card{
    background: var(--paper); border:1px solid var(--border); border-radius: 14px;
    padding: 12pt 12pt; box-shadow: 0 2px 6px rgba(2,6,23,.05); margin: 12pt 0;
  }

  /* badge/chip */
  .badge,.chip{
    display:inline-block; padding:2pt 6pt; border-radius:999px; font-weight:600; font-size:9.5pt;
    background:#eaf3ff; color:#0b63ce;
  }

  /* tables — key/value look */
  table{width:100%; border-collapse: collapse; margin: 10pt 0; background: var(--paper);
        border:1px solid var(--border); border-radius:12px; overflow:hidden;}
  thead th{
    background:#f5f8fd; color:#0b1a34; font-weight:700; font-size:10.8pt; text-transform:uppercase; letter-spacing:.4px;
    border-bottom:1px solid var(--border-strong);
    padding:8pt 10pt;
  }
  tbody tr{background: #fff;}
  tbody tr:nth-child(odd){ background: var(--zebra); }
  th, td{padding:8pt 10pt; vertical-align:top; border-top:1px solid var(--border);}
  tbody tr:first-child th, tbody tr:first-child td{border-top:0}

  /* 1ª colonna = etichetta; 2ª = valore */
  tbody td:first-child, tbody th:first-child{
    width:36%; color:var(--subtle); font-weight:600; text-transform:none; letter-spacing:.2px;
  }
  tbody td:last-child{
    color:#0d1726; font-weight:600;
  }

  /* monospace per valori "tecnici" */
  td:last-child code, td:last-child pre, td:last-child .mono{
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
    font-size: 10.5pt; background: #f4f7fb; padding:2pt 4pt; border-radius:6px;
  }

  /* link "puliti" in stampa */
  a[href]:after{content:"";}

  /* gestione spezzature */
  .card, table, .title-card{break-inside: avoid; page-break-inside: avoid;}
  .break-before{break-before: page; page-break-before: always;}
  .break-after{break-after: page; page-break-after: always;}
</style>
`;

for (const item of items) {
  const bin = item.binary?.data;
  if (!bin) throw new Error("Binary 'data' mancante dopo Read/Write Files.");

  const html = Buffer.from(bin.data, 'base64').toString('utf8');

  // inietta CSS (una sola volta)
  const withCss = html.includes('id="pdf-print-style"')
    ? html
    : html.replace(/<\/head>/i, PRINT_CSS + "\n</head>");

  // ricrea il binario come index.html per Gotenberg
  const buffer = Buffer.from(withCss, 'utf8');
  item.binary.data = await this.helpers.prepareBinaryData(buffer, 'index.html', 'text/html');
}
return items;
